#!/usr/bin/env bash
# Simple restore script for PostgreSQL backup generated by backup.sh.
# Usage: ./restore.sh <backup_file>

set -euo pipefail

if [[ $# -ne 1 ]]; then
  echo "Usage: $0 <backup_file>" >&2
  exit 1
fi
BACKUP_FILE="$1"

if [[ ! -f "$BACKUP_FILE" ]]; then
  echo "Backup file not found: $BACKUP_FILE" >&2
  exit 1
fi

if [[ -z "${DATABASE_URL:-}" ]]; then
  echo "Error: DATABASE_URL not set" >&2
  exit 1
fi

# Parse connection details
export PGPASSWORD=$(echo "$DATABASE_URL" | sed -n 's|.*:\([^:]*\)@.*|\1|p')
HOST=$(echo "$DATABASE_URL" | sed -n 's|postgresql://[^:]*:[^@]*@\([^:/]*\).*|\1|p')
PORT=$(echo "$DATABASE_URL" | sed -n 's|.*:\([0-9]*\)/.*|\1|p')
USER=$(echo "$DATABASE_URL" | sed -n 's|postgresql://\([^:]*\):.*|\1|p')
DB=$(echo "$DATABASE_URL" | sed -n 's|.*/\([^?]*\).*|\1|p')

pg_restore -h "$HOST" -p "${PORT:-5432}" -U "$USER" -d "$DB" -c "$BACKUP_FILE"

echo "Database restored from $BACKUP_FILE"
